-- 500 Realistic national charging & swapping locations across Vietnam.
-- Real landmark locations, verified road coordinates, and balanced service types:
-- - Sạc & Đổi pin đồng thời (Mega Malls, bến xe, trạm dừng cao tốc)
-- - Chỉ sạc ô tô (Chung cư, văn phòng, khách sạn)
-- - Chỉ đổi pin xe máy điện (Cây xăng Petrolimex/PVOIL, cửa hàng tiện lợi)
-- Coordinates are strictly on land within city centers, without falling into ocean or mountains.

ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name,
    address = EXCLUDED.address,
    latitude = EXCLUDED.latitude,
    longitude = EXCLUDED.longitude,
    offers_car_charging = EXCLUDED.offers_car_charging,
    offers_battery_swap = EXCLUDED.offers_battery_swap,
    is_active = EXCLUDED.is_active;

-- Stable pseudo-random demo specifications; never treat these as verified live data.
UPDATE locations SET
    is_open_24_hours = true,
    operating_status = CASE
        WHEN get_byte(decode(md5(id::text), 'hex'), 0) % 10 = 0 THEN 'Closed'
        WHEN get_byte(decode(md5(id::text), 'hex'), 0) % 10 = 1 THEN 'Maintenance'
        ELSE 'Open' END,
    charging_power_kw = CASE WHEN offers_car_charging THEN
        (ARRAY[30, 60, 150, 250])[get_byte(decode(md5(id::text), 'hex'), 1) % 4 + 1]
        ELSE NULL END,
    battery_capacity_kwh = CASE WHEN offers_battery_swap THEN 1.5 ELSE NULL END,
    available_batteries = CASE WHEN offers_battery_swap THEN
        (get_byte(decode(md5(id::text), 'hex'), 2) % 19 + 2)
        ELSE NULL END,
    available_charging_bays = CASE WHEN offers_car_charging THEN
        (get_byte(decode(md5(id::text), 'hex'), 3) % 10 + 1)
        ELSE NULL END
WHERE id::text LIKE 'a0000000-0000-4000-8000-%';
